using NUnit.Framework;

namespace Depths.Tests
{
    /// <summary>
    /// The Warden against the running game: rows recorded by tools/boss-parity.js on 2026-10-06 from
    /// the game's own tickBodies() - a phase-one fight (volleys and sweeps) and one started below a third
    /// of its health (phase three: the wall of statues and the heavier bag). Every 25 ticks: position,
    /// move, moveT, castT, volleyLeft, volleyT, bossCd, phase, the body count, the shells fired and the
    /// player's hp; both streams' draws exact (each statue is a real spawn, two jitter draws apiece).
    /// </summary>
    [TestFixture]
    public sealed class BossParityTests
    {
        static void Check(double hpFrac, double bx, double by, double px, double py, int ticks, int jitterDraws, int runDraws, object[][] rows, int every = 25)
        {
            var run = new RunState(new Rng(4242)) { dungeon = Dungeon.FromSeed(new Rng(4242)) };
            run.state = "playing";
            var p = run.player;
            p.x = p.lagX = px; p.y = p.lagY = py;
            p.hp = p.maxHp = 1e6;
            TickOrder.HitboxX = p.lagX; TickOrder.HitboxY = p.lagY;
            var e = Enemy.Of(BodyKind.Boss, bx, by);
            Spawn.BossInit(e);
            e.noticeTimer = 0; e.hp = e.maxHp * hpFrac;
            run.enemies.Add(e);
            int j0 = run.rng.JitterCalls, r0 = run.rng.RunCalls, row = 0;
            for (int t = 1; t <= ticks; t++)
            {
                p.iframes = 0;
                TickOrder.TickBodies(run);
                if (t % every != 0) continue;
                var w = rows[row++];
                string at = " at tick " + t;
                double D(int k) => System.Convert.ToDouble(w[k]);
                Assert.That(t, Is.EqualTo((int)D(0)));
                Assert.That(e.x, Is.EqualTo(D(1)).Within(1e-6), "x" + at);
                Assert.That(e.y, Is.EqualTo(D(2)).Within(1e-6), "y" + at);
                Assert.That(e.move, Is.EqualTo((string)w[3]), "move" + at);
                Assert.That(e.moveT, Is.EqualTo((int)D(4)), "moveT" + at);
                Assert.That(e.castT, Is.EqualTo((int)D(5)), "castT" + at);
                Assert.That(e.volleyLeft, Is.EqualTo((int)D(6)), "volleyLeft" + at);
                Assert.That(e.volleyT, Is.EqualTo((int)D(7)), "volleyT" + at);
                Assert.That(e.bossCd, Is.EqualTo(D(8)).Within(1e-6), "bossCd" + at);
                Assert.That(e.phase, Is.EqualTo((int)D(9)), "phase" + at);
                Assert.That(run.enemies.Count, Is.EqualTo((int)D(10)), "bodies" + at);
                Assert.That(run.projectiles.Count, Is.EqualTo((int)D(11)), "shells" + at);
                Assert.That(p.hp, Is.EqualTo(D(12)).Within(1e-6), "player hp" + at);
            }
            Assert.That(run.rng.JitterCalls - j0, Is.EqualTo(jitterDraws), "jitter draws");
            Assert.That(run.rng.RunCalls - r0, Is.EqualTo(runDraws), "run draws");
        }

